-- ====================================================================
-- Source: 20260811130000_price_visibility_guardrail_and_trending.sql
-- ====================================================================
-- ============================================================================
-- Price-visibility guardrail
-- ============================================================================
-- The original CHECK only blocked a product from *claiming* a price it
-- doesn't have (show_price = true with NULL price). It never blocked the
-- opposite mistake -- hiding a real price behind "price on request" -- which
-- is exactly the ambiguity that erodes trust on a catalog page. Genuine
-- services (is_service = true) still get to hide price, since those are
-- quoted per request by design; everything else must show its price once
-- one exists.
--
-- Audit: no current seed row actually has this bug (every show_price=false
-- row already has a NULL price), so this UPDATE is a no-op today -- it's
-- here as a safety net for any row that predates this constraint.
UPDATE public.products
SET show_price = true
WHERE price IS NOT NULL AND show_price = false AND is_service = false;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'products_show_price_requires_service_check'
  ) THEN
    ALTER TABLE public.products
      ADD CONSTRAINT products_show_price_requires_service_check
      CHECK (show_price = true OR price IS NULL OR is_service = true);
  END IF;
END $$;

-- ============================================================================
-- "Trending picks" -- a curated shelf from the existing catalog (no new
-- products), surfaced above Categories on Home and on Explore for quick
-- reordering of the items this workforce actually buys daily: self-care
-- basics, snacking, and treats.
-- ============================================================================
UPDATE public.products
SET tags = tags || ARRAY['trending']
WHERE name IN (
  'Face Wash',
  'Face Cream',
  'Body Lotion',
  'Hair Oil',
  'Deodorant',
  'Talcum Powder',
  'Sanitary Pads (Pack)',
  'Mango Juice (300 ml)',
  'KitKat Shake (300 ml)',
  'Mango Ice Cream Cone',
  'Dairy Milk (Bar)',
  'Lays (Pack)'
)
AND NOT ('trending' = ANY(tags));

-- ====================================================================
-- Source: 20260812070000_delivery_batch_rider_self_claim.sql
-- ====================================================================
-- Delivery batches already group orders by delivery window (the underlying
-- mechanism the admin panel calls "Delivery batches"), but nothing tracks
-- who's actually delivering a given trip. Add self-claim: any signed-in
-- ops/admin staff can claim an unassigned batch as themselves, and release
-- it again if plans change. This is intentionally independent of the
-- existing `riders` table (a separate, unused admin-managed roster with no
-- link to an auth account) -- self-claim needs to work for whoever is
-- actually signed into the staff console right now, with zero setup.
ALTER TABLE public.delivery_batches
  ADD COLUMN IF NOT EXISTS assigned_staff_id UUID REFERENCES auth.users(id),
  ADD COLUMN IF NOT EXISTS assigned_staff_email TEXT,
  ADD COLUMN IF NOT EXISTS assigned_at TIMESTAMPTZ;

-- ====================================================================
-- Source: 20260812080000_order_level_staff_assignment.sql
-- ====================================================================
-- Replaces the previous migration's batch-level self-claim: staff think
-- "this order is mine to deliver", not "I claimed an abstract delivery
-- batch". Assignment now lives directly on the order, reusing the existing
-- assigned_employee_id column -- dead weight since the old PIN-based
-- employee login was dropped (no FK, nothing reads/writes it today) --
-- rather than adding a second parallel assignment concept.
ALTER TABLE public.orders RENAME COLUMN assigned_employee_id TO assigned_staff_id;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS assigned_staff_email TEXT;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS assigned_at TIMESTAMPTZ;

-- ====================================================================
-- Source: 20260814060000_drop_legacy_unused_tables.sql
-- ====================================================================
-- Drop legacy tables left over from earlier designs.
--
-- These four are all EMPTY (0 rows) and are NOT referenced anywhere in the
-- application code -- the live role check uses public.user_roles, not these:
--   * staff        -- superseded by user_roles
--   * riders        -- superseded by user_roles + order-level assignment
--   * employees     -- superseded by user_roles
--   * group_orders  -- a feature that was never shipped
--
-- Deliberately NOT dropped (still in use, so they stay):
--   * delivery_batches       -- read by api.functions.ts, holds data
--   * notification_deliveries -- written by notifications-admin.functions.ts
--   * rate_limit_hits, search_analytics -- actively written to
--
-- Safe to run: IF EXISTS makes it a no-op if a table is already gone, and
-- CASCADE removes any dependent policies/constraints those dead tables owned.
-- No live table has a foreign key INTO these (orders.assigned_employee_id is a
-- plain UUID column with no FK), so nothing else is affected.
--
-- After applying, regenerate src/integrations/supabase/types.ts so the
-- TypeScript types no longer describe the removed tables.

DROP TABLE IF EXISTS public.group_orders CASCADE;
DROP TABLE IF EXISTS public.employees CASCADE;
DROP TABLE IF EXISTS public.riders CASCADE;
DROP TABLE IF EXISTS public.staff CASCADE;

-- ====================================================================
-- Source: 20260816090000_catalog_curation.sql
-- ====================================================================
-- Catalog curation pass.
--
-- Findings from auditing the live catalog (12 top-level categories,
-- 45 subcategories, 226 products):
--
--   1. Three top-level categories were renamed at some point but kept their
--      original slugs, so the URL contradicts the page: /c/beauty served
--      "Pharmacy & Personal Care", /c/travel served "e-Seva & Documentation",
--      /c/stay served "Local Assistance".
--   2. Those same three kept their ORIGINAL subcategories too, so e-Seva
--      listed "Flight booking"/"Movie tickets" and Pharmacy listed "Makeup
--      essentials" -- unrelated to any product actually in them.
--   3. All 45 subcategories contain zero products. The category page renders
--      subcategories as ItemCards (add-to-cart "ask" tiles), so each one
--      appeared to be an orderable item that no one can actually fulfil.
--   4. Several products are duplicates of each other with DIFFERENT prices
--      (e.g. "Chicken Biryani" Rs180 vs "Chicken Biryani (Plate)" Rs170,
--      "Paracetamol 500mg strip" Rs25 vs "Paracetamol (Strip)" Rs20).
--   5. A batch of hand-added rows use lowercase names and no unit
--      ("Chicken rice", "Water can", "Cooking oil") next to the curated rows
--      that all follow "Name (unit)" -- so listings look inconsistent.
--   6. Medicines were listed as ordinary add-to-cart products with fixed
--      prices. MyTown is an errand runner, not a licensed pharmacy; selling
--      medicine off a menu misrepresents what actually happens and is the
--      wrong footing legally. They are converted to price-on-request errands.
--
-- Product removals are SOFT (is_available = false) whenever the product is
-- referenced by a past order, so order history keeps rendering correctly;
-- unreferenced rows are deleted outright.

-- ---------------------------------------------------------------------------
-- 1. Slugs that contradict their category name
-- ---------------------------------------------------------------------------
update public.categories set slug = 'pharmacy' where slug = 'beauty';
update public.categories set slug = 'eseva'    where slug = 'travel';
update public.categories set slug = 'assist'   where slug = 'stay';

-- ---------------------------------------------------------------------------
-- 2. Empty subcategories
--
-- Every one of the 45 has no products. They render as orderable tiles, and a
-- third of them describe a different business than their parent. Removing them
-- makes each category page show exactly what it can actually deliver.
-- order_items stores category/subcategory as text snapshots (not foreign
-- keys), so past orders are unaffected.
-- ---------------------------------------------------------------------------
delete from public.categories c
where c.parent_id is not null
  and not exists (select 1 from public.products p where p.category_id = c.id);

-- ---------------------------------------------------------------------------
-- 3. Duplicate products
--
-- Keeps the row whose name follows the "Name (unit)" convention and whose
-- price matches the rest of its category.
-- ---------------------------------------------------------------------------
-- Duplicate names, listed once and reused by both statements below:
--   'Chicken Biryani'           -> keep "Chicken Biryani (Plate)"
--   'Chicken rice'              -> keep "Chicken Fried Rice (Plate)"
--   'Fish fry'                  -> keep "Fish 65 (Plate)"
--   'Paracetamol 500mg strip'   -> keep "Paracetamol (Strip)" in Pharmacy
--   'Phone recharge assistance' -> keep "Mobile Recharge"
--   'Ticket Booking'            -> keep the specific "Bus Ticket Booking Help"
--   'Need Anything'             -> keep "Custom Request"
--   'Lodge Booking Assistance'  -> keep "Hotel Booking Assistance"

-- Deactivate the ones that appear in order history (preserves past orders)...
update public.products p
set is_available = false, updated_at = now()
where p.name in (
        'Chicken Biryani', 'Chicken rice', 'Fish fry', 'Paracetamol 500mg strip',
        'Phone recharge assistance', 'Ticket Booking', 'Need Anything',
        'Lodge Booking Assistance')
  and exists (select 1 from public.order_items oi where oi.product_id = p.id);

-- ...and delete the ones never ordered.
delete from public.products p
where p.name in (
        'Chicken Biryani', 'Chicken rice', 'Fish fry', 'Paracetamol 500mg strip',
        'Phone recharge assistance', 'Ticket Booking', 'Need Anything',
        'Lodge Booking Assistance')
  and not exists (select 1 from public.order_items oi where oi.product_id = p.id);

-- ---------------------------------------------------------------------------
-- 4. Naming consistency
--
-- The curated catalog uses Title Case plus an explicit unit, which is what
-- makes a listing scannable ("Idli (2 pcs)" tells you what Rs15 buys).
-- These rows were added later without it.
-- ---------------------------------------------------------------------------
update public.products set name = 'Baby Care Essentials'   where name = 'Baby products';
update public.products set name = 'Cooking Oil (1 L)'      where name = 'Cooking oil';
update public.products set name = 'Detergent Powder (1 kg)' where name = 'Detergent';
update public.products set name = 'Drinking Water Can (20 L)' where name = 'Water can';
update public.products set name = 'Local Pickup & Drop'    where name = 'Local delivery';
update public.products set name = 'Tailor Pickup & Drop'   where name = 'Tailor pickup';
update public.products set name = 'Amul Milk (500 ml)'     where name = 'Amul Milk 500ml';
update public.products set name = 'Sugar (1 kg)'           where name = 'Sugar 1kg';

-- Dish names that don't say what the dish is. "Ghee Roast" on its own reads as
-- a chicken preparation in most of India; here it's the dosa.
update public.products set name = 'Ghee Roast Dosa (1 pc)' where name = 'Ghee Roast';
update public.products set name = 'Onion Dosa (1 pc)'      where name = 'Onion Dosa';
update public.products set name = 'Rava Dosa (1 pc)'       where name = 'Rava Dosa';
update public.products set name = 'Filter Coffee (150 ml)' where name = 'Filter Coffee';
update public.products set name = 'Tea (150 ml)'           where name = 'Tea';

-- ---------------------------------------------------------------------------
-- 5. Medicines: sold products -> price-on-request errands
--
-- MyTown fetches things from local shops; it does not stock or dispense
-- medicine. Listing a fixed price implies we sell it. As service items they
-- route through the same "we'll pick this up and confirm" flow as every other
-- errand, and staff can check what's actually available at the chemist.
-- ---------------------------------------------------------------------------
update public.products
set is_service  = true,
    show_price  = false,
    price       = null,
    description = coalesce(nullif(description, ''), 'We pick this up from a local pharmacy. Carry a prescription if one is required.'),
    updated_at  = now()
where name in (
  'Paracetamol (Strip)',
  'Antacid (Strip)',
  'ORS (Pack)',
  'Cough Syrup',
  'Pain Relief Spray',
  'Antiseptic Liquid (100 ml)',
  'Band-Aid (Pack)',
  'Cotton Roll',
  'Digital Thermometer',
  'Heating Patch',
  'Pregnancy Test Kit'
);

-- ---------------------------------------------------------------------------
-- 6. Top-level ordering
--
-- Ordered by how often a small town actually opens them: everyday food and
-- essentials first, planned/occasional purchases after, services last.
-- ---------------------------------------------------------------------------
update public.categories set sort_order = 1  where slug = 'food';
update public.categories set sort_order = 2  where slug = 'daily';
update public.categories set sort_order = 3  where slug = 'fruits';
update public.categories set sort_order = 4  where slug = 'beverages';
update public.categories set sort_order = 5  where slug = 'bakery';
update public.categories set sort_order = 6  where slug = 'snacks';
update public.categories set sort_order = 7  where slug = 'desserts';
update public.categories set sort_order = 8  where slug = 'cakes';
update public.categories set sort_order = 9  where slug = 'pharmacy';
update public.categories set sort_order = 10 where slug = 'assist';
update public.categories set sort_order = 11 where slug = 'eseva';
update public.categories set sort_order = 12 where slug = 'rentals';

-- ====================================================================
-- Source: 20260817080000_product_detail_descriptions.sql
-- ====================================================================
-- Product detail: a long description, and real copy for the services.
--
-- Every product currently has at most a one-line `description`. That's enough
-- for a card, but not enough to decide from -- and for the assistance services
-- it isn't enough to even understand what's being offered. "Parent Assistance",
-- "Guest Pickup" and "Shopping Assistance" are titles, not explanations; a
-- customer reading them has no idea what would actually happen, what it costs,
-- or what we need from them.
--
-- `description_long` backs the product detail sheet. It answers three questions
-- in order: what this is, how it works, and what we need from you.

alter table public.products
  add column if not exists description_long text;

comment on column public.products.description_long is
  'Full description shown in the product detail sheet. Plain text, paragraphs separated by blank lines. Falls back to `description` when empty.';

-- ---------------------------------------------------------------------------
-- Assistance services -- the ones a one-liner genuinely fails
-- ---------------------------------------------------------------------------
update public.products set description_long =
  'Someone from MyTown visits your parents or elderly relatives at home and helps with whatever they need that day — collecting medicines, paying a bill, a bank or government office visit, or simply checking in and calling you afterwards.

Useful if you work away from Karimangalam and can''t be there yourself. We''ll call you after every visit and tell you honestly how they are.

Tell us their address, what they need help with, and a time that suits them. We''ll confirm on call before going.'
where name = 'Parent Assistance';

update public.products set description_long =
  'We receive your guest at the bus stand, railway station or drop point and bring them safely to your address — helpful when you can''t leave work or home.

Our staff will call your guest before they arrive so they know who to look for, and call you once they''ve been dropped off.

Share the arrival time, the pickup point and both phone numbers. Vehicle charges are confirmed with you before pickup.'
where name = 'Guest Pickup';

update public.products set description_long =
  'Tell us what you need and we''ll buy it from local shops for you — clothes, a gift, hardware, school supplies, anything available in and around Karimangalam.

We''ll send you photos and prices from the shop before paying, so you choose while sitting at home. Nothing is bought without your confirmation.

You pay the shop price plus our service charge on delivery. If it''s unavailable anywhere we''ll tell you rather than buying a substitute.'
where name = 'Shopping Assistance';

update public.products set description_long =
  'We stand in the queue for you — at a government office, a bank, an EB office or a hospital counter — and call you when it''s nearly your turn so you only need to arrive for the few minutes that require you in person.

Best for long-wait counters where most of the morning is spent simply waiting.

Tell us the office, the work involved and the day. We''ll confirm the timing and what documents you should carry.'
where name = 'Queue Standing';

update public.products set description_long =
  'Help with government paperwork end to end: which form applies, filling it correctly, arranging the supporting documents, and submitting it at the right office.

Covers certificates, applications, corrections and renewals. If a document is missing we''ll tell you what to arrange before we go, so a trip isn''t wasted.

Bring the details on a call and we''ll tell you honestly whether it''s something we can help with.'
where name = 'Government Office Assistance';

update public.products set description_long =
  'We collect a parcel or document from you and drop it at a courier office, or at an address within Karimangalam.

Good for anything that''s awkward to leave home for — a returned online order, documents to a relative, keys to a family member.

Tell us the pickup and drop points and roughly when. Courier charges, if any, are paid at actual and shown to you.'
where name = 'Parcel Pickup / Courier Drop';

update public.products set description_long =
  'Can''t find what you need listed? Describe it in your own words and we''ll tell you whether we can do it, what it will cost, and how long it takes.

Most requests in and around Karimangalam are possible — this exists so you never have to force what you want into a category that doesn''t fit.

There''s no charge for asking. We confirm everything on call before starting.'
where name = 'Custom Request';

-- ---------------------------------------------------------------------------
-- Pharmacy: the request-based framing needs stating plainly
-- ---------------------------------------------------------------------------
update public.products set description_long =
  'MyTown is not a pharmacy — we collect this for you from a licensed local chemist and deliver it.

Because of that, the price is whatever the chemist charges on the day, and we confirm it with you before buying. If they don''t stock it we''ll check another shop rather than substituting something different.

For anything prescription-only, keep the prescription ready: the chemist will ask for it, and we can''t collect the medicine without it.'
where is_service = true
  and show_price = false
  and category_id in (select id from public.categories where slug = 'pharmacy');

-- ====================================================================
-- Source: 20260817090000_catalog_phase4_events_services.sql
-- ====================================================================
-- Phase 4 catalogue recuration.
--
-- The catalogue was seeded for a demo. This reshapes it around how a Tamil
-- Nadu town of a few thousand people actually shops, based on the owner's
-- read of his own customers:
--
--   * Events are a real, recurring local need with no listing at all today --
--     weddings, Valaikappu, Manjal Neerattu Vizha, Gruhapravesam, birthdays.
--     Every one of them involves a hall, catering, seating, decoration and
--     flowers, and every one is currently arranged by phoning around.
--   * Electrician/plumber/AC sat inside "Local Assistance" alongside errands,
--     which are a different kind of job with different expectations.
--   * "Hotel Booking Assistance" carries a connotation nobody wants attached
--     to a family service, and "Lodge Booking" was worse.
--   * Flower Delivery had no obvious buyer as a single stem; at event scale
--     it does.
--
-- Everything new is enquiry-only (is_service, price on request): MyTown
-- brokers these rather than performing them, and a fixed price would imply
-- otherwise. Prices are agreed on call before anything is committed.

-- ---------------------------------------------------------------------------
-- 1. Rename away the double meaning
-- ---------------------------------------------------------------------------
update public.products
set name = 'Guest & Family Stay Booking',
    description = 'Rooms arranged for visiting family and guests.',
    description_long = 'We find and book a clean, respectable room nearby for family or guests visiting you — for a function, a hospital stay, or a few days'' visit.

We check the room, confirm the tariff and hold the booking in your name. You''re told the exact price before anything is confirmed.

Tell us the dates, how many people, and roughly the budget. If nothing suitable is free we''ll say so rather than putting your guests somewhere we wouldn''t put our own.',
    updated_at = now()
where name = 'Hotel Booking Assistance';

-- ---------------------------------------------------------------------------
-- 2. Home Services -- trades, split out from errands
-- ---------------------------------------------------------------------------
insert into public.categories (name, slug, parent_id, icon_key, sort_order)
values ('Home Services', 'home-services', null, 'wrench', 10)
on conflict (slug) do nothing;

-- Move the trades across from Local Assistance.
update public.products
set category_id = (select id from public.categories where slug = 'home-services'),
    tags = array['home-service'],
    updated_at = now()
where name in (
  'Electrician Visit',
  'Plumber Visit',
  'AC Service',
  'House Cleaning (2 hr)'
);

insert into public.products
  (category_id, name, description, description_long, is_service, show_price, price, is_available, tags, sort_order)
select
  (select id from public.categories where slug = 'home-services'),
  v.name, v.short, v.long, true, false, null, true, array['home-service'], v.ord
from (values
  ('Carpenter Visit',
   'Furniture repair, fittings, door and window work.',
   'A local carpenter for repairs and fittings — a door that won''t close, a broken cot, shelves to put up, window work.

Tell us what needs doing and send a photo if you can; that usually tells the carpenter whether it''s a quick job or a half-day, so the estimate you get is realistic.

Materials are bought at actual cost with your approval. Labour is confirmed before work starts.', 5),
  ('Appliance Repair',
   'Fan, mixer, washing machine, fridge, TV.',
   'Repair for household appliances — ceiling fans, mixers, washing machines, fridges, televisions.

Tell us the appliance, the make if you know it, and what''s wrong. We''ll arrange someone who works on that type rather than a general hand.

If it turns out to be beyond economical repair we''ll tell you that plainly instead of charging for a visit that fixes nothing.', 6),
  ('Pest Control',
   'Cockroach, termite and mosquito treatment.',
   'Treatment for cockroaches, termites, mosquitoes and rodents, arranged with a local operator.

Tell us the problem, the rough size of the house, and whether there are young children or pets — that changes what can safely be used.

You''ll be told what''s being applied, how long to stay out afterwards, and the price, all before the visit.', 7),
  ('House Painting',
   'Interior and exterior painting.',
   'Painting for a room, a full house, or an exterior — including before a function or after a repair.

We arrange the painter, and paint is bought at actual cost with your approval so you''re not paying a marked-up rate.

Tell us the rooms or the area and we''ll arrange a look before quoting. Nothing starts until the estimate is agreed.', 8),
  ('Water Tank Cleaning',
   'Overhead and sump tank cleaning.',
   'Cleaning for overhead tanks and sumps — worth doing before the monsoon and after any supply disruption.

Includes draining, scrubbing and refilling. Tell us the tank size and where it is; access matters for the quote.

Price is confirmed before the visit.', 9)
) as v(name, short, long, ord)
where not exists (select 1 from public.products p where p.name = v.name);

-- ---------------------------------------------------------------------------
-- 3. Events & Occasions -- the genuinely new category
-- ---------------------------------------------------------------------------
insert into public.categories (name, slug, parent_id, icon_key, sort_order)
values ('Events & Occasions', 'events', null, 'party-popper', 11)
on conflict (slug) do nothing;

-- Flower delivery belongs here: at event scale it has an obvious buyer.
update public.products
set category_id = (select id from public.categories where slug = 'events'),
    name = 'Flowers & Garlands',
    description = 'Loose flowers and garlands, including bulk for functions.',
    description_long = 'Flowers and garlands from local sellers — a daily string for the pooja room, or bulk orders for a function.

For events, tell us the date and roughly how much you need and we''ll arrange it with a seller who can actually supply that quantity on the morning, rather than promising and falling short.

Price varies with the season and the flower; we confirm before buying.',
    tags = array['event'],
    updated_at = now()
where name = 'Flower Delivery';

insert into public.products
  (category_id, name, description, description_long, is_service, show_price, price, is_available, tags, sort_order)
select
  (select id from public.categories where slug = 'events'),
  v.name, v.short, v.long, true, false, null, true, array['event'], v.ord
from (values
  ('Function Hall Booking',
   'Halls for weddings, receptions and functions.',
   'We check which halls are free on your date, what they charge, and what''s included — chairs, kitchen, generator, parking — then hold the one you choose.

Halls quote differently depending on who asks and what''s bundled, so we get it in plain terms and give you the comparison rather than a single number.

Tell us the date, expected guests and rough budget. Booking is confirmed only after you agree the amount.', 1),
  ('Event Catering',
   'Cooks and catering for functions, any scale.',
   'Catering for functions — from a small home gathering to a full wedding meal.

Tell us the date, the headcount and the menu you have in mind (or ask us to suggest one). We arrange cooks who regularly do that scale, because a cook who is excellent for thirty people is not automatically right for three hundred.

Per-plate rate is confirmed in writing before the date. Changes to headcount are normal — tell us as early as you can.', 2),
  ('Tent, Chairs & Seating',
   'Shamiana, chairs, tables and stage setup.',
   'Tent house arrangements — shamiana, chairs, tables, stage, carpet and lighting, delivered and set up.

Tell us the date, the venue and the headcount. We''ll arrange delivery the day before where the venue allows it, so nothing is being assembled while guests arrive.

Damage and delay terms are explained upfront so there are no surprises afterwards.', 3),
  ('Event Decoration',
   'Stage, entrance and hall decoration.',
   'Decoration for functions — stage backdrop, entrance arch, hall and car decoration.

Send a photo of anything you''ve seen and liked; that communicates far better than a description, and decorators quote more accurately from it.

Tell us the date and venue. Quote is confirmed before work begins.', 4),
  ('Event Photography',
   'Photo and video for functions.',
   'Photographers and videographers for weddings, functions and family occasions.

Tell us the date, the hours you need covered, and whether you want video as well. We''ll share what''s included — prints, album, edited video — because that''s where quotes usually differ rather than the day rate.

Advance and delivery timelines are agreed before booking.', 5),
  ('Priest Booking',
   'Purohit arranged for ceremonies.',
   'A purohit arranged for ceremonies — Gruhapravesam, Valaikappu, Manjal Neerattu Vizha, naming, and wedding rituals.

Tell us the ceremony, the date and time, and your family''s tradition, so we arrange someone who performs it the way you expect.

We''ll also pass on the list of items to arrange beforehand, so nothing is missing on the morning.', 6),
  ('Invitation Printing',
   'Wedding and function invitation cards.',
   'Invitation cards printed locally — wedding, house-warming, ear-piercing, birthday.

Send the wording and we''ll bring proofs before printing. Getting names and dates checked at proof stage is the whole point; a mistake found after printing means printing again.

Quantity, paper and price are confirmed with you first.', 7),
  ('Event Cleaning',
   'Venue cleaning before and after a function.',
   'Cleaning a venue or home before guests arrive and clearing up afterwards.

The after-function clear-up is the one people forget to arrange and most regret — tell us the venue and rough size and we''ll arrange enough hands to finish it the same night.

Price confirmed before the date.', 8)
) as v(name, short, long, ord)
where not exists (select 1 from public.products p where p.name = v.name);

-- ---------------------------------------------------------------------------
-- 4. Salon: appointments at real shops, not a service we perform
-- ---------------------------------------------------------------------------
update public.products
set name = 'Salon Appointment',
    description = 'Booked for you at a local salon.',
    description_long = 'We book your slot at a local salon — haircut, shave, facial, threading, bridal work — so you''re not waiting your turn on a busy day.

MyTown does not send anyone to your home for this: these are appointments at shops in town that you can see and judge for yourself. Tell us what you need and when, and we''ll confirm which salon and what time.

You pay the salon directly at their rate.',
    updated_at = now()
where name = 'Salon Haircut (at home)';

update public.products
set name = 'Threading & Waxing Appointment',
    description = 'Booked for you at a local salon.',
    description_long = 'A slot booked at a local salon for threading or waxing, at a time that suits you.

Tell us what you need and roughly when. We''ll confirm the salon and the time, and you pay them directly at their rate.',
    updated_at = now()
where name = 'Threading';

-- ---------------------------------------------------------------------------
-- 5. Local Assistance: one clear list of errands, now the trades have moved
-- ---------------------------------------------------------------------------
update public.products
set tags = array['local-service'], updated_at = now()
where category_id = (select id from public.categories where slug = 'assist');

update public.categories
set name = 'Local Help & Errands'
where slug = 'assist';

-- Cook stays an errand (someone cooking in your kitchen), not a trade.
update public.products
set description_long = 'A cook comes to your kitchen and prepares the day''s meal — useful during illness, after a birth, when guests are staying, or for elderly parents living alone.

Tell us how many people, roughly what you eat, and the time. Groceries can be bought by us beforehand if you''d rather not arrange them.

Rate is per meal and confirmed before the first visit.'
where name = 'Cook (per meal)' and description_long is null;

