-- ====================================================================
-- Source: 20260817110000_order_identity_and_contact_snapshot.sql
-- ====================================================================
-- Fix cross-account identity bleed between customers.
--
-- THE BUG
--
-- `customers` is keyed by phone number, and createOrder did an unconditional
-- upsert on it:
--
--     UPDATE customers SET name = <typed at checkout>, address = ...
--     WHERE id = <row matching that phone>
--
-- with no check on who owns that row. So anyone who typed a phone number at
-- guest checkout overwrote the name and address of the *account* that owns
-- that number, and their order attached to that account's customer row --
-- which, via the orders owner-read policy, made it visible in that account's
-- order list. Two people sharing one number therefore shared one identity:
-- last writer won the name, and each could see the other's orders.
--
-- THE MODEL, AFTER THIS
--
--   * A row with user_id IS NOT NULL is an ACCOUNT. It belongs to exactly one
--     auth user (enforced by the partial unique index below) and is only ever
--     written by that user.
--   * A row with user_id IS NULL is a GUEST record, still keyed by phone.
--     Guest checkout may reuse and update these; it may never touch an
--     account row.
--
-- Identity is therefore the auth user, not the phone number. Phone becomes
-- what it always should have been: a contact detail on the order.
--
-- WHY ORDERS GET THEIR OWN CONTACT COLUMNS
--
-- Delivery details lived only on the customer row, so an order had no record
-- of where it was actually going -- editing a profile silently rewrote the
-- delivery address of every past order, and re-pointing an order between
-- customer rows (which claiming a guest order now does) would lose them
-- entirely. Orders now snapshot the details given at checkout, which is both
-- correct history and what staff need to see on the board.

BEGIN;

-- 1. Contact snapshot on the order itself ----------------------------------
ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS contact_name text,
  ADD COLUMN IF NOT EXISTS contact_phone text,
  ADD COLUMN IF NOT EXISTS delivery_address text,
  ADD COLUMN IF NOT EXISTS delivery_landmark text;

-- Backfill from the customer row each order is currently attached to. This
-- MUST run before the de-duplication below re-points any orders, so every
-- order captures the details it was actually placed with.
UPDATE public.orders o
SET contact_name = c.name,
    contact_phone = c.phone,
    delivery_address = c.address,
    delivery_landmark = c.landmark
FROM public.customers c
WHERE c.id = o.customer_id
  AND o.contact_name IS NULL;

-- 2. One account row per auth user -----------------------------------------
-- Duplicates are reachable today: PIN signup inserts a row for a user, and
-- linkOrderToAccount could later stamp the same user_id onto a different
-- guest row. getMyProfile does .maybeSingle() on user_id, so a duplicate
-- makes the profile lookup error out -- part of why the account panel went
-- blank for some people.
--
-- Keep the earliest row per user as canonical, move that user's orders onto
-- it, and release the rest back to being guest records rather than deleting
-- anything.
WITH ranked AS (
  SELECT id,
         user_id,
         row_number() OVER (PARTITION BY user_id ORDER BY created_at, id) AS rn
  FROM public.customers
  WHERE user_id IS NOT NULL
),
canonical AS (
  SELECT user_id, id AS keep_id FROM ranked WHERE rn = 1
),
dupes AS (
  SELECT r.id AS dupe_id, c.keep_id
  FROM ranked r
  JOIN canonical c ON c.user_id = r.user_id
  WHERE r.rn > 1
)
UPDATE public.orders o
SET customer_id = d.keep_id
FROM dupes d
WHERE o.customer_id = d.dupe_id;

WITH ranked AS (
  SELECT id,
         row_number() OVER (PARTITION BY user_id ORDER BY created_at, id) AS rn
  FROM public.customers
  WHERE user_id IS NOT NULL
)
UPDATE public.customers c
SET user_id = NULL
FROM ranked r
WHERE c.id = r.id AND r.rn > 1;

CREATE UNIQUE INDEX IF NOT EXISTS customers_user_id_unique
  ON public.customers (user_id)
  WHERE user_id IS NOT NULL;

-- 3. Guest lookups are always "by phone AND unowned" now, so index that -----
CREATE INDEX IF NOT EXISTS customers_guest_phone_idx
  ON public.customers (phone)
  WHERE user_id IS NULL;

COMMIT;

-- ====================================================================
-- Source: 20260817120000_shorten_long_category_names.sql
-- ====================================================================
-- Shorten the three category names that don't fit a home-page tile.
--
-- The home grid is four columns on a phone, so a tile label has room for two
-- short lines. Measured against the live catalogue, exactly three names
-- overflowed it and rendered as "Pharmacy &…", which reads as unfinished
-- rather than as a name.
--
-- Shortened rather than given more room: making the tiles wider means fewer
-- categories visible without scrolling, and these three all say the same thing
-- in fewer words. The slugs are untouched, so no link or bookmark changes.

BEGIN;

UPDATE public.categories SET name = 'Food & Meals'    WHERE slug = 'food';
UPDATE public.categories SET name = 'Ice Cream'       WHERE slug = 'desserts';
UPDATE public.categories SET name = 'Pharmacy & Care' WHERE slug = 'pharmacy';

COMMIT;

-- ====================================================================
-- Source: 20260817130000_shorten_remaining_category_names.sql
-- ====================================================================
-- Three category names still overflowed a four-column phone tile.
--
-- The home grid gives a tile roughly 72px of inner width, which fits two
-- short lines. These three each contain one word longer than a line
-- ("Beverages", "Chocolates", "Documentation"), so they were cut mid-word:
-- "Juices & Beverage", "Snacks &...", "e-Seva &...".
--
-- Shortened rather than widened, for the same reason as the previous three:
-- wider tiles mean fewer categories visible without scrolling. Slugs are
-- untouched, so no link, bookmark or QR code changes.

BEGIN;

UPDATE public.categories SET name = 'Juices & Drinks' WHERE slug = 'beverages';
UPDATE public.categories SET name = 'Snacks & Sweets' WHERE slug = 'snacks';
UPDATE public.categories SET name = 'e-Seva'          WHERE slug = 'eseva';

COMMIT;

-- ====================================================================
-- Source: 20260817140000_delivery_pincode.sql
-- ====================================================================
-- Capture a pincode with every delivery address.
--
-- Addresses are free text today ("Dharmapuri Main Rd"), which is enough for a
-- rider who already knows the town and nothing more than that. A pincode is
-- the smallest addition that makes an address machine-readable, and it is the
-- piece three separate things need:
--
--   * Serviceability. "Do we deliver there?" currently has no answer the app
--     can give -- an order is accepted first and sorted out on the phone
--     afterwards.
--   * A second town. locations already exists and orders already carry
--     location_id, so the missing link between "where the customer is" and
--     "which location serves them" is exactly this field.
--   * Routing and batching. Grouping a run by area needs something more
--     stable than the prose someone typed.
--
-- Nullable on purpose: every existing order predates the field, and checkout
-- must keep working for anyone who doesn't know theirs. It is validated as six
-- digits when given, never required.

BEGIN;

ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS delivery_pincode text;

ALTER TABLE public.customers
  ADD COLUMN IF NOT EXISTS pincode text;

-- Six digits, or nothing. Guards against a phone number or a house number
-- being typed into the field.
ALTER TABLE public.orders
  DROP CONSTRAINT IF EXISTS orders_delivery_pincode_format;
ALTER TABLE public.orders
  ADD CONSTRAINT orders_delivery_pincode_format
  CHECK (delivery_pincode IS NULL OR delivery_pincode ~ '^[1-9][0-9]{5}$');

ALTER TABLE public.customers
  DROP CONSTRAINT IF EXISTS customers_pincode_format;
ALTER TABLE public.customers
  ADD CONSTRAINT customers_pincode_format
  CHECK (pincode IS NULL OR pincode ~ '^[1-9][0-9]{5}$');

-- Delivery runs are grouped by area, so this is the column that gets filtered.
CREATE INDEX IF NOT EXISTS orders_delivery_pincode_idx
  ON public.orders (delivery_pincode)
  WHERE delivery_pincode IS NOT NULL;

COMMIT;

-- ====================================================================
-- Source: 20260818075000_order_rating.sql
-- ====================================================================
-- A delivered order has no feedback loop today: nothing captures whether it
-- actually went well, so a bad vendor or rider only surfaces once someone
-- complains by phone -- which in a small town is also how you lose trust.
--
-- One column, not a table: a rating is a fact about the order it belongs to,
-- not an entity with its own lifecycle, and there is exactly one per order.
alter table public.orders
  add column if not exists rating smallint check (rating between 1 and 5);

comment on column public.orders.rating is
  'Customer''s 1-5 star rating, settable only once the order is delivered. Null means not yet rated.';
